bool ActionManager::canResumeConstructionOf(const Object *object, const Object *b, CommandSourceType commandSource)
{
	if (object == 0 || b == 0)
		return false;
	if (!object->getTemplate()->isKindOf(KINDOF_DOZER))
		return false;
	Relationship r = object->getRelationship(b);
	if (r != ALLIES)
		return false;
	if (!b->testStatus((ObjectStatusTypes)r))
		return false;
	if (object->isEffectivelyDead())
		return false;
	ObjectID ben = b->getSoleHealingBenefactor();
	if (ben != 0 && ben != object->getID())
		return false;
	return true;
}

