// The action manager singleton (retail VA 0x00E030E8).
ActionManager *TheActionManager = 0;

bool ActionManager::rva0041CC65(const SpecialPowerTemplate *power, const Coord3D *pos)
{
	Region3D extent;
	TheTerrainLogic->getMaximumPathfindExtent(&extent);
	Real radius = power->getFO()->m_radiusCursorRadius;
	extent.hi.x -= radius;
	extent.hi.y -= radius;
	extent.lo.x += radius;
	extent.lo.y += radius;
	if (pos->x > extent.lo.x && pos->x < extent.hi.x && pos->y > extent.lo.y && pos->y < extent.hi.y)
		return true;
	return false;
}
